import fs from 'fs';
import path from 'path';

const todosFile = path.join(process.cwd(), 'todos.json');

// Load todos from file
function loadTodos() {
  try {
    if (fs.existsSync(todosFile)) {
      const data = fs.readFileSync(todosFile, 'utf8');
      return JSON.parse(data);
    }
  } catch (error) {
    console.error('Error loading todos:', error.message);
  }
  return [];
}

// Save todos to file
function saveTodos(todos) {
  fs.writeFileSync(todosFile, JSON.stringify(todos, null, 2));
}

// Add a todo
function addTodo(text) {
  const todos = loadTodos();
  todos.push(text);
  saveTodos(todos);
  console.log(`Added: ${text}`);
}

// List todos
function listTodos() {
  const todos = loadTodos();
  if (todos.length === 0) {
    console.log('No todos yet.');
    return;
  }
  todos.forEach((todo, index) => {
    console.log(`${index + 1}. ${todo}`);
  });
}

// Main
const args = process.argv.slice(2);
const command = args[0];

if (command === 'add' && args.length > 1) {
  const text = args.slice(1).join(' ');
  addTodo(text);
} else if (command === 'list') {
  listTodos();
} else {
  console.log('Usage:');
  console.log('  node todo.js add <text>  - Add a todo');
  console.log('  node todo.js list        - List all todos');
}

