import fs from 'fs';
import path from 'path';

const todosFile = path.join(process.cwd(), 'todos.json');

// Load todos from file
function loadTodos() {
  try {
    if (fs.existsSync(todosFile)) {
      const data = fs.readFileSync(todosFile, 'utf8');
      return JSON.parse(data);
    }
  } catch (error) {
    console.error('Error loading todos:', error.message);
  }
  return [];
}

// Save todos to file
function saveTodos(todos) {
  fs.writeFileSync(todosFile, JSON.stringify(todos, null, 2));
}

// Add a todo
function addTodo(text) {
  if (!text || text.trim() === '') {
    console.error('Error: todo text cannot be empty');
    process.exit(1);
  }
  const todos = loadTodos();
  todos.push({ text, completed: false });
  saveTodos(todos);
  console.log(`Added: ${text}`);
}

// List todos
function listTodos() {
  const todos = loadTodos();
  if (todos.length === 0) {
    console.log('No todos yet.');
    return;
  }
  todos.forEach((todo, index) => {
    const checkbox = todo.completed ? '[x]' : '[ ]';
    console.log(`${index + 1}. ${checkbox} ${todo.text}`);
  });
}

// Mark todo as done
function markDone(n) {
  const todos = loadTodos();
  const index = parseInt(n, 10) - 1;

  if (isNaN(index) || index < 0 || index >= todos.length) {
    console.error(`Error: invalid todo number ${n}`);
    process.exit(1);
  }

  todos[index].completed = true;
  saveTodos(todos);
  console.log(`Marked done: ${todos[index].text}`);
}

// Clear completed todos
function clearCompleted() {
  const todos = loadTodos();
  const completedCount = todos.filter(t => t.completed).length;
  const filtered = todos.filter(t => !t.completed);
  saveTodos(filtered);
  console.log(`Removed ${completedCount} completed item(s).`);
}

// Main
const args = process.argv.slice(2);
const command = args[0];

if (command === 'add' && args.length > 1) {
  const text = args.slice(1).join(' ');
  addTodo(text);
} else if (command === 'add') {
  console.error('Error: todo text cannot be empty');
  process.exit(1);
} else if (command === 'list') {
  listTodos();
} else if (command === 'done' && args.length > 1) {
  markDone(args[1]);
} else if (command === 'clear') {
  clearCompleted();
} else {
  console.log('Usage:');
  console.log('  node todo.js add <text>  - Add a todo');
  console.log('  node todo.js list        - List all todos');
  console.log('  node todo.js done <n>    - Mark todo n as complete');
  console.log('  node todo.js clear       - Remove completed items');
}
